{"content": """"
multiline_grep — Python-native multiline grep engine
====================================================

架构：5 层管道
  GrepConfig → FileDiscoverer → FileFilter → PatternEngine → ResultAggregator → OutputFormatter

每层职责清晰、可独立替换、可独立测试。

Usage:
    from multiline_grep import multiline_grep, format_results
    results = multiline_grep("import.*\\n.*from", ".", file_glob="*.py")
    print(format_results(results))
"""

import os
import re
import subprocess
from concurrent.futures import ThreadPoolExecutor, as_completed
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable, Optional


# ═══════════════════════════════════════════════════════════════════
# Stage 0 — Configuration
# ═══════════════════════════════════════════════════════════════════

@dataclass
class GrepConfig:
    """单一配置对象，贯穿整个管道。"""
    pattern: str
    path: str = "."
    multiline: bool = False
    auto_detect: bool = True
    file_glob: Optional[str] = None
    exclude: list = field(default_factory=list)      # 自定义排除路径（glob）
    git_aware: bool = False                          # 仅搜索 git diff 的文件
    max_results: int = 200
    context: int = 0
    count_mode: bool = False                         # 只计数，不返回匹配内容
    max_file_size: int = 10 * 1024 * 1024            # 10 MB
    parallel: bool = False                           # 启用并行（多文件）
    parallel_workers: int = 4
    pattern_engine: str = "re"                       # re | regex (PCRE2)

    def __post_init__(self):
        if self.auto_detect and not self.multiline and '\\n' in self.pattern:
            self.multiline = True


# ═══════════════════════════════════════════════════════════════════
# Stage 1 — Matches data model
# ═══════════════════════════════════════════════════════════════════

class GrepMatch:
    """单个匹配结果。__slots__ 减少内存开销（批量场景显著）。"""
    __slots__ = ('path', 'line_number', 'line_content', 'match_text',
                 'context_before', 'context_after', 'column')

    def __init__(self, path: str, line_number: int, line_content: str,
                 match_text: str = "",
                 context_before: Optional[list] = None,
                 context_after: Optional[list] = None,
                 column: int = 0):
        self.path = path
        self.line_number = line_number
        self.line_content = line_content
        self.match_text = match_text
        self.context_before = context_before or []
        self.context_after = context_after or []
        self.column = column

    def __repr__(self):
        return f"<GrepMatch {self.path}:{self.line_number}:{self.line_content[:60]}>"


# ═══════════════════════════════════════════════════════════════════
# Stage 2 — File Discovery
# ═══════════════════════════════════════════════════════════════════

_TEXT_EXTENSIONS = frozenset({
    '.py', '.js', '.ts', '.tsx', '.jsx', '.mjs', '.cjs', '.mts', '.cts',
    '.json', '.yaml', '.yml', '.toml', '.ini', '.cfg', '.conf',
    '.md', '.mdx', '.txt', '.rst', '.adoc',
    '.html', '.htm', '.xhtml', '.css', '.scss', '.sass', '.less', '.vue', '.svelte',
    '.c', '.h', '.cpp', '.hpp', '.cc', '.cxx', '.hh', '.hxx',
    '.java', '.kt', '.kts', '.go', '.rs', '.rb', '.php', '.pl', '.pm',
    '.sh', '.bash', '.zsh', '.fish', '.ps1', '.bat', '.cmd',
    '.xml', '.svg', '.rtf',
    '.dockerfile', '.env', '.gitignore', '.gitattributes', '.editorconfig',
    '.tf', '.tfvars', '.hcl',
    '.sql', '.graphql', '.gql',
    '.proto', '.gradle', '.cmake',
    '.makefile', '.mk',
    '.patch', '.diff',
})

# 默认排除目录（不参与任何搜索）
_DEFAULT_EXCLUDE = {'node_modules', '.git', '__pycache__', '.venv', 'venv',
                    '.tox', '.eggs', 'dist', 'build', '.next', '.turbo',
                    '.nyc_output', 'coverage', '.pytest_cache', '.mypy_cache',
                    '.ruff_cache', '.cache', '.gitlab', '.svn', '.hg',
                    '.idea', '.vscode', 'target', 'bin', 'obj'}


def _is_binary_file(path: str) -> bool:
    """扩展名 + 头 8KB null byte sniff。"""
    ext = Path(path).suffix.lower()
    if ext in _TEXT_EXTENSIONS:
        return False
    try:
        with open(path, 'rb') as f:
            head = f.read(8192)
            return b'\0' in head
    except Exception:
        return True  # 读不了视为 binary


def _should_skip_file(path: str,
                       max_size: int,
                       exclude_patterns: list) -> Optional[str]:
    """返回跳过原因，None 表示保留。"""
    try:
        size = os.path.getsize(path)
    except OSError:
        return "unreadable"
    if size == 0:
        return "empty"
    if size > max_size:
        return f"too large ({size} bytes)"
    for ex in exclude_patterns:
        if Path(path).match(ex):
            return f"excluded by {ex!r}"
    return None


def discover_files(config: GrepConfig) -> list:
    """Stage 1: 发现待搜索文件列表。

    支线：
      - git_aware: 只返回 git diff 修改的文件
      - 否则全量 rglob + 默认排除
    """
    base = Path(config.path)
    if base.is_file():
        return [str(base)]

    # 默认排除 + 用户自定义
    exclude_set = _DEFAULT_EXCLUDE | set(config.exclude)

    if config.git_aware:
        return _discover_git_files(base, exclude_set)

    # 全量 rglob
    pattern = config.file_glob or "**/*"
    files = []
    for fpath in base.rglob(pattern):
        if not fpath.is_file():
            continue
        # 排除目录检查：路径中任一组件在 exclude_set 里
        if any(part in exclude_set for part in fpath.parts):
            continue
        files.append(str(fpath))
    return sorted(files)


def _discover_git_files(base: Path, exclude_set: set) -> list:
    """git diff --name-only + git ls-files 收集变更文件。"""
    try:
        result = subprocess.run(
            ["git", "diff", "--name-only", "--cached", "--diff-filter=ACMR"],
            capture_output=True, text=True, timeout=10, cwd=base,
        )
        staged = result.stdout.strip().split('\n') if result.stdout.strip() else []
    except Exception:
        staged = []

    try:
        result = subprocess.run(
            ["git", "diff", "--name-only", "--diff-filter=ACMR"],
            capture_output=True, text=True, timeout=10, cwd=base,
        )
        working = result.stdout.strip().split('\n') if result.stdout.strip() else []
    except Exception:
        working = []

    try:
        result = subprocess.run(
            ["git", "ls-files", "--others", "--exclude-standard"],
            capture_output=True, text=True, timeout=10, cwd=base,
        )
        untracked = result.stdout.strip().split('\n') if result.stdout.strip() else []
    except Exception:
        untracked = []

    seen = set()
    files = []
    for name in staged + working + untracked:
        name = name.strip()
        if not name or name in seen:
            continue
        seen.add(name)
        full = str(base / name)
        if not os.path.isfile(full):
            continue
        if any(part in exclude_set for part in name.split('/')):
            continue
        files.append(full)

    # fallback: 如果没有 git 变更文件，全量扫描（干净 checkout）
    if not files:
        pattern = "**/*"
        for fpath in base.rglob(pattern):
            if not fpath.is_file():
                continue
            if any(part in exclude_set for part in fpath.parts):
                continue
            files.append(str(fpath))

    return sorted(files)


# ═══════════════════════════════════════════════════════════════════
# Stage 3 — Pattern Engine
# ═══════════════════════════════════════════════════════════════════

class PatternEngine:
    """可插拔的模式匹配引擎基类。"""

    def compile(self, pattern: str, multiline: bool):
        raise NotImplementedError

    def search(self, compiled, text: str):
        raise NotImplementedError

    def finditer(self, compiled, text: str):
        raise NotImplementedError


class ReEngine(PatternEngine):
    """Python re 引擎。"""

    def compile(self, pattern: str, multiline: bool):
        flags = re.DOTALL | re.MULTILINE if multiline else re.MULTILINE
        try:
            return re.compile(pattern, flags)
        except re.error:
            raise ValueError(f"Invalid regex pattern: {pattern}")

    def search(self, compiled, text: str):
        return compiled.search(text)

    def finditer(self, compiled, text: str):
        return compiled.finditer(text)


_RE_ENGINE = ReEngine()


def _get_engine(cfg: GrepConfig) -> PatternEngine:
    """工厂：根据配置返回引擎实例。"""
    if cfg.pattern_engine == "regex":
        try:
            import regex as _regex
        except ImportError:
            raise ImportError(
                "regex (PyPI) required for pattern_engine='regex'. "
                "Install: pip install regex"
            )

        class RegexEngine(PatternEngine):
            def compile(self, pattern, multiline):
                flags = (_regex.DOTALL | _regex.MULTILINE if multiline
                         else _regex.MULTILINE)
                try:
                    return _regex.compile(pattern, flags)
                except _regex.error:
                    raise ValueError(f"Invalid regex pattern: {pattern}")

            def search(self, compiled, text):
                return compiled.search(text)

            def finditer(self, compiled, text):
                return compiled.finditer(text)

        return RegexEngine()
    return _RE_ENGINE


# ═══════════════════════════════════════════════════════════════════
# Stage 4 — 核心匹配（文件级）
# ═══════════════════════════════════════════════════════════════════

def _search_file(file_path: str, cfg: GrepConfig, engine: PatternEngine) -> list:
    """在单个文件中搜索，返回 list[GrepMatch]。"""
    skip = _should_skip_file(file_path, cfg.max_file_size, cfg.exclude)
    if skip:
        return []
    if _is_binary_file(file_path):
        return []

    if cfg.multiline:
        return _search_file_multiline(file_path, cfg, engine)
    else:
        return _search_file_line(file_path, cfg, engine)


def _search_file_line(file_path: str, cfg: GrepConfig,
                       engine: PatternEngine) -> list:
    """逐行匹配。"""
    try:
        with open(file_path, 'r', encoding='utf-8', errors='replace') as f:
            lines = f.readlines()
    except Exception:
        return []

    compiled = engine.compile(cfg.pattern, multiline=False)
    results = []
    for i, line in enumerate(lines):
        m = compiled.search(line)
        if not m:
            continue
        before = lines[max(0, i - cfg.context):i] if cfg.context > 0 else []
        after = lines[i + 1:i + 1 + cfg.context] if cfg.context > 0 else []
        results.append(GrepMatch(
            path=file_path,
            line_number=i + 1,
            line_content=line.rstrip('\n'),
            match_text=line.rstrip('\n'),
            context_before=[l.rstrip('\n') for l in before],
            context_after=[l.rstrip('\n') for l in after],
            column=m.start(),
        ))
        if not cfg.count_mode and len(results) >= cfg.max_results:
            return results
    return results


def _search_file_multiline(file_path: str, cfg: GrepConfig,
                            engine: PatternEngine) -> list:
    """跨行匹配（全文件读取）。"""
    try:
        with open(file_path, 'r', encoding='utf-8', errors='replace') as f:
            content = f.read()
    except Exception:
        return []

    compiled = engine.compile(cfg.pattern, multiline=True)
    results = []
    # 计数模式：只返回 1 个空匹配表示"有匹配"
    if cfg.count_mode:
        if compiled.search(content):
            results.append(GrepMatch(
                path=file_path, line_number=0, line_content="",
                match_text="",
            ))
        return results

    for m in compiled.finditer(content):
        start_line = content[:m.start()].count('\n') + 1
        match_text = m.group()

        if cfg.context > 0:
            all_lines = content.split('\n')
            idx = start_line - 1
            before = all_lines[max(0, idx - cfg.context):idx]
            after = all_lines[idx + 1:idx + 1 + cfg.context]
        else:
            before, after = [], []

        first_line = match_text.split('\n', 1)[0] if match_text else ""

        results.append(GrepMatch(
            path=file_path,
            line_number=start_line,
            line_content=first_line,
            match_text=match_text,
            context_before=before,
            context_after=after,
            column=m.start(),
        ))
        if len(results) >= cfg.max_results:
            return results
    return results


# ═══════════════════════════════════════════════════════════════════
# Stage 5 — Result Aggregation
# ═══════════════════════════════════════════════════════════════════

@dataclass
class GrepStats:
    files_scanned: int = 0
    files_matched: int = 0
    total_matches: int = 0
    files_skipped: int = 0


def run_pipeline(cfg: GrepConfig) -> tuple:
    """执行完整搜索管道。

    Returns:
        (list[GrepMatch], GrepStats)
    """
    engine = _get_engine(cfg)

    # Stage 1+2: 发现 + 过滤（合并为一个 pass 减少开销）
    files = discover_files(cfg)

    stats = GrepStats()
    all_results = []

    if cfg.parallel and len(files) > 1:
        # 并行模式
        with ThreadPoolExecutor(max_workers=cfg.parallel_workers) as pool:
            future_map = {
                pool.submit(_search_file, f, cfg, engine): f
                for f in files
            }
            for future in as_completed(future_map):
                try:
                    file_results = future.result(timeout=60)
                except Exception:
                    file_results = []
                all_results.extend(file_results)
                stats.files_scanned += 1
                if file_results:
                    stats.files_matched += 1
                    stats.total_matches += len(file_results)
                if not file_results and _should_skip_file(
                    future_map[future], cfg.max_file_size, cfg.exclude
                ):
                    stats.files_skipped += 1
    else:
        # 串行模式
        for f in files:
            file_results = _search_file(f, cfg, engine)
            stats.files_scanned += 1
            if file_results:
                stats.files_matched += 1
                stats.total_matches += len(file_results)
                all_results.extend(file_results)
            elif _should_skip_file(f, cfg.max_file_size, cfg.exclude):
                stats.files_skipped += 1

    return all_results, stats


# ═══════════════════════════════════════════════════════════════════
# Stage 6 — Output Formatting
# ═══════════════════════════════════════════════════════════════════

def format_results(results: list, max_chars: int = 4000,
                   show_context: bool = True) -> str:
    """格式化为人类可读字符串。

    Args:
        results: list[GrepMatch]
        max_chars: 最大输出字符数
        show_context: 是否显示 context_before/context_after
    """
    if not results:
        return "(no matches)"

    lines = []
    for r in results:
        is_multiline = bool(r.match_text and '\n' in r.match_text)
        line_str = f"{r.path}:{r.line_number}:{r.line_content}"
        if r.column:
            line_str += f" (col {r.column})"
        lines.append(line_str)

        # 上下文输出（context）
        if show_context and (r.context_before or r.context_after):
            if r.context_before:
                for cl in r.context_before:
                    lines.append(f"  -{cl}")
            if is_multiline:
                match_lines = r.match_text.split('\n')
                n = len(match_lines)
                lines.append(f"  ─ match ({n} lines) ─")
                for ml in match_lines[:5]:
                    lines.append(f"  │ {ml}")
                if n > 5:
                    lines.append(f"  │ … ({n - 5} more lines)")
            if r.context_after:
                for cl in r.context_after:
                    lines.append(f"  +{cl}")
        elif is_multiline:
            match_lines = r.match_text.split('\n')
            n = len(match_lines)
            lines.append(f"  ─ match ({n} lines) ─")
            for ml in match_lines[:5]:
                lines.append(f"  │ {ml}")
            if n > 5:
                lines.append(f"  │ … ({n - 5} more lines)")

    output = '\n'.join(lines)
    if len(output) > max_chars:
        output = output[:max_chars] + f"\n… (truncated, {len(results)} matches total)"
    return output


def format_count(results: list, stats: GrepStats) -> str:
    """计数模式输出：文件级匹配统计。"""
    # 按文件分组
    per_file = {}
    for r in results:
        per_file[r.path] = per_file.get(r.path, 0) + 1

    lines = []
    for fpath, count in sorted(per_file.items()):
        lines.append(f"{fpath}:{count}")
    lines.append("---")
    lines.append(f"{stats.files_matched} files matched, {stats.files_scanned} scanned, {stats.files_skipped} skipped")
    return '\n'.join(lines)


def format_stats(stats: GrepStats, results: list) -> str:
    """完整统计数据。"""
    return (
        f"Files scanned:  {stats.files_scanned}\n"
        f"Files matched:  {stats.files_matched}\n"
        f"Files skipped:  {stats.files_skipped}\n"
        f"Total matches:  {stats.total_matches}"
    )


def grep_json(results: list) -> list:
    """JSON 兼容格式，供程序化消费。"""
    return [
        {
            "path": r.path,
            "line": r.line_number,
            "column": r.column,
            "content": r.line_content,
            "match": r.match_text,
            "context_before": r.context_before,
            "context_after": r.context_after,
        }
        for r in results
    ]


# ═══════════════════════════════════════════════════════════════════
# Backward-compatible public API
# ═══════════════════════════════════════════════════════════════════

def multiline_grep(pattern: str, path: str = ".",
                   multiline: bool = False,
                   file_glob: Optional[str] = None,
                   max_results: int = 200,
                   context: int = 0,
                   auto_detect: bool = True,
                   git_aware: bool = False,
                   exclude: Optional[list] = None,
                   count_mode: bool = False,
                   parallel: bool = False,
                   pattern_engine: str = "re") -> list:
    """统一 grep 入口（向后兼容 v1）。

    完整参数见 GrepConfig。
    """
    cfg = GrepConfig(
        pattern=pattern,
        path=path,
        multiline=multiline,
        auto_detect=auto_detect,
        file_glob=file_glob,
        max_results=max_results,
        context=context,
        git_aware=git_aware,
        exclude=exclude or [],
        count_mode=count_mode,
        parallel=parallel,
        pattern_engine=pattern_engine,
    )
    results, _ = run_pipeline(cfg)
    return results
